import type { BankQuestion } from "@/lib/bank";

/** Ratio, Proportion and Mixtures (Quantitative Aptitude): 139 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"quant-ratio-1","question":"₹700 is divided in the ratio 3 : 4. The larger share is:","options":["₹300","₹350","₹400","₹450"],"answer":2,"explanation":"One part = 700 ÷ 7 = 100, so the larger share is 4 × 100 = ₹400.","difficulty":"easy"},
  {"id":"quant-ratio-2","question":"If A : B = 2 : 3 and B : C = 4 : 5, then A : C is:","options":["8 : 15","2 : 5","5 : 6","3 : 10"],"answer":0,"explanation":"A : C = (2/3) × (4/5) = 8/15.","difficulty":"moderate"},
  {"id":"quant-ratio-3","question":"The ages of A and B are in the ratio 4 : 5. After 5 years the ratio will be 5 : 6. What is A’s present age?","options":["15 years","20 years","25 years","30 years"],"answer":1,"explanation":"(4k + 5)/(5k + 5) = 5/6 gives 24k + 30 = 25k + 25, so k = 5 and A is 20.","difficulty":"hard"},
  {"id":"quant-ratio-4","question":"A 30-litre mixture has milk and water in the ratio 7 : 3. How much water must be added to make it 3 : 2?","options":["3 litres","5 litres","7 litres","9 litres"],"answer":1,"explanation":"Milk = 21 L, water = 9 L. For 3 : 2, water must be 21 × 2/3 = 14 L, so add 5 L.","difficulty":"very-hard"},
  {"id":"quant-ratio-5","question":"If a : b = 3 : 5, then (2a + b) : (a + 2b) is:","options":["6 : 10","1 : 1","13 : 11","11 : 13"],"answer":3,"explanation":"Put a = 3, b = 5: (6 + 5) : (3 + 10) = 11 : 13.","difficulty":"easy","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ratio-6","question":"The fourth proportional to 6, 9 and 14 is:","options":["21","16","18","12"],"answer":0,"explanation":"6 : 9 = 14 : x gives x = 9 × 14/6 = 21.","difficulty":"easy","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-ratio-7","question":"If A : B = 3 : 4, B : C = 5 : 6 and C : D = 7 : 8, then A : D is:","options":["3 : 8","15 : 32","35 : 64","21 : 32"],"answer":2,"explanation":"A/D = (A/B)(B/C)(C/D) = (3/4)(5/6)(7/8) = 105/192 = 35/64.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ratio-8","question":"₹1,890 is divided among A, B and C so that A : B = 2 : 3 and B : C = 4 : 5. A's share is:","options":["₹810","₹540","₹648","₹432"],"answer":3,"explanation":"A : B : C = 8 : 12 : 15 (35 parts). One part = 1,890/35 = 54, so A = 8 × 54 = ₹432.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"quant-ratio-9","question":"A 60-litre mixture contains milk and water in the ratio 2 : 1. How much water must be added to make the ratio 1 : 2?","options":["40 litres","80 litres","60 litres","20 litres"],"answer":2,"explanation":"Milk = 40 L, water = 20 L. For 1 : 2 the water must be 80 L, so add 60 L.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ratio-10","question":"In what ratio must tea at ₹60 per kg be mixed with tea at ₹80 per kg so that the mixture costs ₹65 per kg?","options":["3 : 1","2 : 1","4 : 1","1 : 3"],"answer":0,"explanation":"Alligation: (80 − 65) : (65 − 60) = 15 : 5 = 3 : 1 (cheaper : dearer).","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-ratio-11","question":"The present ages of A and B are in the ratio 5 : 7. Eight years ago the ratio was 3 : 5. The sum of their present ages is:","options":["48 years","60 years","40 years","36 years"],"answer":0,"explanation":"(5x − 8)/(7x − 8) = 3/5 → 25x − 40 = 21x − 24 → x = 4. Ages 20 and 28, sum 48.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ratio-12","question":"A bag has 1-rupee, 50-paise and 25-paise coins in the ratio 3 : 4 : 5, totalling ₹250. The number of 50-paise coins is:","options":["100","160","120","200"],"answer":1,"explanation":"Value = 3x × 1 + 4x × 0.5 + 5x × 0.25 = 6.25x = 250 → x = 40. 50-paise coins = 4 × 40 = 160.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-ratio-13","question":"An 80-litre mixture has milk and water in the ratio 3 : 1. 20 litres of the mixture are taken out and replaced by water. The new ratio of milk to water is:","options":["2 : 1","3 : 2","9 : 7","7 : 9"],"answer":2,"explanation":"Removing 20 L keeps the ratio: 60 L left with 45 L milk and 15 L water. Adding 20 L water: 45 : 35 = 9 : 7.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ratio-14","question":"The incomes of A and B are in the ratio 4 : 5 and their expenditures in the ratio 7 : 9. If each saves ₹3,000, A's income is:","options":["₹20,000","₹21,000","₹30,000","₹24,000"],"answer":3,"explanation":"4x − 7y = 3,000 and 5x − 9y = 3,000. Subtracting gives x = 2y, so 8y − 7y = 3,000, y = 3,000 and x = 6,000. A's income = 4x = ₹24,000.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-ratio-15","question":"A invests ₹20,000 for 12 months and B invests ₹30,000 for 8 months in a business. Out of a profit of ₹36,000, B's share is:","options":["₹14,400","₹18,000","₹24,000","₹21,600"],"answer":1,"explanation":"Capital × time: 20,000 × 12 = 2,40,000 and 30,000 × 8 = 2,40,000, ratio 1 : 1. B gets ₹18,000. Dividing in the ratio of capital alone (2 : 3) gives the wrong ₹21,600.","difficulty":"hard","source":"SSC CGL · SBI PO"},
  {"id":"quant-ratio-16","question":"Alloy P has copper and zinc in the ratio 2 : 3 and alloy Q in the ratio 3 : 2. If P and Q are mixed in the ratio 2 : 3 by weight, the ratio of copper to zinc in the new alloy is:","options":["1 : 1","5 : 6","12 : 13","13 : 12"],"answer":3,"explanation":"2 kg of P has 0.8 copper and 1.2 zinc; 3 kg of Q has 1.8 copper and 1.2 zinc. Totals: copper 2.6, zinc 2.4, ratio 13 : 12.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ratio-17","question":"A grocer mixes rice costing ₹30 per kg with rice costing ₹45 per kg and sells the mixture at ₹44 per kg, gaining 10%. The ratio of the cheaper to the dearer rice is:","options":["1 : 2","1 : 4","4 : 1","2 : 1"],"answer":0,"explanation":"Cost price of the mixture = 44/1.1 = ₹40 per kg. Alligation: (45 − 40) : (40 − 30) = 5 : 10 = 1 : 2.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-ratio-18","question":"A container has 40 litres of pure milk. 8 litres are drawn out and replaced with water, and this is done once more. The quantity of milk now left is:","options":["25.6 litres","26 litres","24 litres","32 litres"],"answer":0,"explanation":"Milk left = 40 × (1 − 8/40)² = 40 × 0.8² = 40 × 0.64 = 25.6 L. 24 L assumes 8 L of milk is removed each time.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ratio-19","question":"A milkman has 20 litres of milk costing ₹40 per litre. He adds water and sells the mixture at ₹40 per litre, making a profit of 25%. The quantity of water added is:","options":["4 litres","8 litres","10 litres","5 litres"],"answer":3,"explanation":"Cost = ₹800; for 25% profit he must collect ₹1,000 at ₹40 per litre, i.e. sell 25 litres. Water added = 25 − 20 = 5 L.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-ratio-20","question":"If x : y = 3 : 4 and x² + y² = 400, then x + y is:","options":["24","28","20","32"],"answer":1,"explanation":"x = 3k, y = 4k: 9k² + 16k² = 25k² = 400, k = 4. x = 12, y = 16, x + y = 28.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ratio-21","question":"Three vessels contain milk and water in the ratios 1 : 2, 2 : 3 and 3 : 4. Equal volumes from all three are mixed. The ratio of milk to water in the mixture is:","options":["193 : 122","122 : 193","2 : 3","6 : 24"],"answer":1,"explanation":"Milk fractions 1/3, 2/5, 3/7; with LCM 105 per vessel: milk 35 + 42 + 45 = 122, water 70 + 63 + 60 = 193. Ratio 122 : 193. Adding the ratio terms directly (6 : 9) is wrong because the vessels' totals differ.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-ratio-22","question":"How many of the following statements are correct?\n1. If a : b = 2 : 3 and b : c = 2 : 3, then a : c = 4 : 9.\n2. The mean proportional between 4 and 25 is 10.\n3. If a/b = c/d, then (a + b)/(a − b) = (c + d)/(c − d).\n4. Doubling the quantity of every component of a mixture changes its ratio.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"1 is true (2/3 × 2/3 = 4/9). 2 is true (√100 = 10). 3 is true (componendo and dividendo). 4 is false: scaling every part keeps the ratio. Three statements are correct.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"quant-ratio-23","question":"A starts a business with ₹50,000. After 3 months B joins with ₹40,000, and 3 months after that A withdraws ₹20,000. At the end of the year the profit is shared between A and B in the ratio:","options":["3 : 4","5 : 4","4 : 3","1 : 1"],"answer":2,"explanation":"A: 50,000 × 6 + 30,000 × 6 = 4,80,000. B: 40,000 × 9 = 3,60,000. Ratio 480 : 360 = 4 : 3.","difficulty":"very-hard","source":"SSC CGL · SBI PO"},
  {"id":"quant-ratio-24","question":"Alloy A contains gold and copper in the ratio 7 : 2 and alloy B in the ratio 7 : 11. Equal weights of the two alloys are melted together. The ratio of gold to copper in the new alloy is:","options":["5 : 7","7 : 5","14 : 13","1 : 1"],"answer":1,"explanation":"Per unit weight: gold = 7/9 + 7/18 = 21/18, copper = 2/9 + 11/18 = 15/18. Ratio 21 : 15 = 7 : 5.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id": "quant-ratio-25", "question": "What is the mean proportional between 9 and 16?", "options": ["12.5", "12", "25", "144"], "answer": 1, "explanation": "Mean proportional = √(9 × 16) = √144 = 12. 12.5 is the arithmetic mean.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "quant-ratio-26", "question": "₹5,400 is divided among A, B and C in the ratio 1/2 : 1/3 : 1/6. What is B's share?", "options": ["₹1,800", "₹2,700", "₹900", "₹1,200"], "answer": 0, "explanation": "Multiply by 6: 1/2 : 1/3 : 1/6 = 3 : 2 : 1. B = 2/6 × 5,400 = ₹1,800. ₹2,700 is A's share.", "difficulty": "moderate", "source": "SSC CGL"},
  {"id": "quant-ratio-27", "question": "Two numbers are in the ratio 3 : 5. If 9 is added to each, the ratio becomes 3 : 4. What is the larger number?", "options": ["9", "25", "20", "15"], "answer": 3, "explanation": "(3x + 9)/(5x + 9) = 3/4 → 12x + 36 = 15x + 27 → x = 3. The numbers are 9 and 15.", "difficulty": "moderate", "source": "SSC CGL"},
  {"id": "quant-ratio-28", "question": "The salaries of A and B are in the ratio 2 : 3. If each gets a raise of ₹5,000, the ratio becomes 3 : 4. What is B's present salary?", "options": ["₹10,000", "₹20,000", "₹15,000", "₹12,000"], "answer": 2, "explanation": "(2x + 5,000)/(3x + 5,000) = 3/4 → 8x + 20,000 = 9x + 15,000 → x = 5,000. B = 3x = ₹15,000.", "difficulty": "hard", "source": "SSC CGL"},
  {"id": "quant-ratio-29", "question": "A 40-litre mixture contains milk and water in the ratio 3 : 1. How many litres of the mixture must be taken out and replaced with pure milk to make the ratio 4 : 1?", "options": ["10 litres", "8 litres", "5 litres", "12 litres"], "answer": 1, "explanation": "Milk 30, water 10. Removing x litres removes 0.25x water; water left = 10 − 0.25x must be 1/5 of 40 = 8 → x = 8 litres. 10 litres is the milk to add without removing anything.", "difficulty": "hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-ratio-30", "question": "A, B and C invest capitals in the ratio 3 : 4 : 5 for 4, 3 and 2 months respectively. Out of a profit of ₹34,000, what is C's share?", "options": ["₹10,000", "₹14,167", "₹12,000", "₹11,333"], "answer": 0, "explanation": "Profit ratio = 3×4 : 4×3 : 5×2 = 12 : 12 : 10 (34 parts). C = 10/34 × 34,000 = ₹10,000. ₹14,167 ignores the time.", "difficulty": "hard", "source": "SSC CGL"},
  {"id": "quant-ratio-31", "question": "A milkman buys milk at ₹48 per litre, mixes water with it and sells the mixture at ₹54 per litre, gaining 35%. What is the ratio of water to milk in the mixture?", "options": ["1 : 8", "1 : 4", "5 : 1", "1 : 5"], "answer": 3, "explanation": "Cost price of the mixture = 54 ÷ 1.35 = ₹40 per litre. By alligation (milk 48, water 0): milk : water = (40 − 0) : (48 − 40) = 40 : 8 = 5 : 1, so water : milk = 1 : 5.", "difficulty": "very-hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-ratio-32", "question": "Three numbers are in the ratio 2 : 3 : 5 and the sum of their squares is 1,368. What is the sum of the numbers?", "options": ["36", "50", "60", "72"], "answer": 2, "explanation": "(4 + 9 + 25)x² = 38x² = 1,368 → x² = 36 → x = 6. The numbers are 12, 18 and 30, total 60.", "difficulty": "very-hard", "source": "SSC CGL"},
  {"id": "quant-ratio-33", "question": "A vessel contains 60 litres of pure milk. 6 litres are drawn out and replaced with water, and this is done three times in all. How much milk is left?", "options": ["42 litres", "43.74 litres", "48.6 litres", "45 litres"], "answer": 1, "explanation": "Milk left = 60 × (1 − 6/60)³ = 60 × 0.9³ = 60 × 0.729 = 43.74 litres. 42 litres simply subtracts 18 litres.", "difficulty": "very-hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-ratio-34", "question": "The incomes of A, B and C are in the ratio 5 : 7 : 9 and their expenditures in the ratio 3 : 5 : 6. If A saves one-fifth of his income, what is the ratio of their savings?", "options": ["3 : 1 : 3", "1 : 1 : 1", "2 : 2 : 3", "3 : 2 : 3"], "answer": 0, "explanation": "Incomes 5x, 7x, 9x. A spends 4x = 3y → y = 4x/3. B spends 20x/3, saving 7x − 20x/3 = x/3. C spends 8x, saving x. A saves x. Ratio x : x/3 : x = 3 : 1 : 3.", "difficulty": "very-hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-ratio-35", "question": "What is the third proportional to 9 and 12?", "options": ["15", "10.5", "16", "18"], "answer": 2, "explanation": "If 9 : 12 = 12 : x, then x = 144/9 = 16.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-ratio-36", "question": "What is the duplicate ratio of 3 : 4?", "options": ["√3 : 2", "27 : 64", "6 : 8", "9 : 16"], "answer": 3, "explanation": "The duplicate ratio is the ratio of the squares: 3² : 4² = 9 : 16. 27 : 64 is the triplicate ratio.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-ratio-37", "question": "What is the compound ratio of 2 : 3, 6 : 5 and 5 : 8?", "options": ["13 : 16", "1 : 2", "2 : 1", "3 : 4"], "answer": 1, "explanation": "Multiply the antecedents and consequents: (2 × 6 × 5) : (3 × 5 × 8) = 60 : 120 = 1 : 2.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-ratio-38", "question": "If (x + y) : (x − y) = 7 : 3, then x : y is:", "options": ["5 : 2", "10 : 3", "7 : 3", "2 : 5"], "answer": 0, "explanation": "By componendo–dividendo, x : y = (7 + 3) : (7 − 3) = 10 : 4 = 5 : 2.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-ratio-39", "question": "₹3,000 is divided among A, B and C so that A gets half of what B and C get together, and B gets one-fourth of what A and C get together. What is C's share?", "options": ["₹1,000", "₹1,400", "₹1,200", "₹600"], "answer": 1, "explanation": "A = (B + C)/2 means A is 1/3 of the total = ₹1,000; B = (A + C)/4 means B is 1/5 of the total = ₹600. C = 3,000 − 1,600 = ₹1,400.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-ratio-40", "question": "The salaries of A, B and C are in the ratio 5 : 7 : 9. If C earns ₹8,000 more than A, what is B's salary?", "options": ["₹14,000", "₹10,000", "₹28,000", "₹18,000"], "answer": 0, "explanation": "C − A = 9 − 5 = 4 parts = ₹8,000, so 1 part = ₹2,000 and B = 7 × 2,000 = ₹14,000. ₹28,000 takes ₹8,000 as 2 parts.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-ratio-41", "question": "In a class the ratio of boys to girls is 7 : 5. If 8 boys leave and 4 girls join, the ratio becomes 1 : 1. How many students are there now?", "options": ["64", "76", "72", "68"], "answer": 3, "explanation": "7k − 8 = 5k + 4 gives k = 6: originally 42 boys and 30 girls. Now 34 + 34 = 68. 72 is the original strength.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-ratio-42", "question": "x varies directly as the square of y, and x = 12 when y = 2. What is x when y = 5?", "options": ["50", "75", "60", "30"], "answer": 1, "explanation": "x = ky²: 12 = 4k, so k = 3 and x = 3 × 25 = 75. Treating it as simple direct variation gives 30.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-ratio-43", "question": "₹2,600 is divided among A, B and C such that 2A = 3B = 4C. What is A's share?", "options": ["₹1,040", "₹800", "₹1,200", "₹600"], "answer": 2, "explanation": "2A = 3B = 4C = k gives A : B : C = 1/2 : 1/3 : 1/4 = 6 : 4 : 3, so A = 6/13 × 2,600 = ₹1,200. Reading the ratio as 2 : 3 : 4 is the trap.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-ratio-44", "question": "The price of a diamond varies as the square of its weight. A diamond worth ₹36,000 breaks into three pieces whose weights are in the ratio 1 : 2 : 3. What is the loss?", "options": ["₹22,000", "₹24,000", "₹14,000", "₹18,000"], "answer": 0, "explanation": "Take weight 6 units, so value ∝ 36. The pieces are worth 1 + 4 + 9 = 14 units, i.e. 14/36 × 36,000 = ₹14,000. Loss = ₹22,000; ₹14,000 is what remains.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-ratio-45", "question": "Vessel P contains milk and water in the ratio 5 : 3 and vessel Q in the ratio 3 : 1. In what ratio should the contents of P and Q be mixed to get milk and water in the ratio 2 : 1?", "options": ["2 : 1", "1 : 2", "1 : 1", "3 : 2"], "answer": 0, "explanation": "Milk fractions: P = 5/8, Q = 3/4, target = 2/3. Alligation: P : Q = (3/4 − 2/3) : (2/3 − 5/8) = 1/12 : 1/24 = 2 : 1.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-ratio-46", "question": "A and B invest in a business in the ratio 2 : 3. A is the working partner and gets 10% of the profit as salary; the rest is shared in the ratio of capital. Out of a profit of ₹50,000, how much does A get in all?", "options": ["₹25,000", "₹18,000", "₹23,000", "₹20,000"], "answer": 2, "explanation": "Salary = ₹5,000; the remaining ₹45,000 is shared 2 : 3, giving A ₹18,000. A's total = ₹23,000. ₹18,000 forgets the salary.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-ratio-47", "question": "The ages of a father and his son are in the ratio 7 : 2. After 10 years the ratio will be 9 : 4. How old was the father when the son was born?", "options": ["30 years", "25 years", "20 years", "35 years"], "answer": 1, "explanation": "(7k + 10)/(2k + 10) = 9/4 gives 28k + 40 = 18k + 90, so k = 5: father 35, son 10. The father was 35 − 10 = 25 when the son was born.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-ratio-48", "question": "A bag contains ₹5, ₹2 and ₹1 coins whose total values are in the ratio 4 : 3 : 2. If the bag holds ₹450 in all, how many ₹2 coins are there?", "options": ["150", "75", "50", "100"], "answer": 1, "explanation": "The values are 4/9, 3/9 and 2/9 of ₹450 = ₹200, ₹150 and ₹100, so there are 150 ÷ 2 = 75 two-rupee coins. 150 confuses value with number.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-ratio-49", "question": "A can contains milk and water in the ratio 4 : 1. When 10 litres of the mixture are drawn off and replaced with water, the ratio becomes 2 : 3. How many litres did the can hold?", "options": ["25 litres", "20 litres", "30 litres", "40 litres"], "answer": 1, "explanation": "Milk falls from 4/5 to 2/5 of the can, i.e. it is halved, so (1 − 10/V) = 1/2 and V = 20 litres.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-ratio-50", "question": "If a/b = c/d = e/f = 3, what is (2a² + 3c² + 4e²)/(2b² + 3d² + 4f²)?", "options": ["9", "3", "√3", "27"], "answer": 0, "explanation": "a = 3b, c = 3d, e = 3f, so every term in the numerator is 9 times the matching term in the denominator; the ratio is 9.", "difficulty": "hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-ratio-51", "question": "If (√(x + 3) + √(x − 3))/(√(x + 3) − √(x − 3)) = 2, what is x?", "options": ["3", "15/4", "9/4", "5"], "answer": 1, "explanation": "Componendo–dividendo gives √(x + 3)/√(x − 3) = 3/1, so (x + 3)/(x − 3) = 9, i.e. 8x = 30 and x = 15/4.", "difficulty": "hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-ratio-52", "question": "The numbers of students in three classes are in the ratio 2 : 3 : 5. If 20 students are added to each class, the ratio becomes 4 : 5 : 7. How many students were there in all originally?", "options": ["80", "120", "160", "100"], "answer": 3, "explanation": "(2k + 20)/(3k + 20) = 4/5 gives k = 10, so the classes had 20, 30 and 50 students (100 in all). Check: 40 : 50 : 70 = 4 : 5 : 7.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-ratio-53", "question": "How many of the following statements are correct?\n1. The mean proportional between 0.32 and 0.02 is 0.08.\n2. If a : b = c : d, then (a + b) : (a − b) = (c + d) : (c − d).\n3. The sub-duplicate ratio of 16 : 25 is 4 : 5.\n4. If x : y = 2 : 3, then (x + 5) : (y + 5) = 7 : 8.", "options": ["Only one", "Only three", "Only two", "All four"], "answer": 1, "explanation": "1: √(0.0064) = 0.08, true. 2: componendo–dividendo, true. 3: √16 : √25 = 4 : 5, true. 4 is false: adding 5 to both changes the ratio by an amount depending on the actual values (x = 4, y = 6 gives 9 : 11).", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-ratio-54", "question": "Three containers with capacities in the ratio 4 : 8 : 2 are full of milk–water mixtures in the ratios 3 : 1, 5 : 3 and 1 : 1 respectively. All three are emptied into one large vessel. What is the ratio of milk to water in it?", "options": ["9 : 5", "2 : 1", "3 : 2", "5 : 3"], "answer": 0, "explanation": "Milk = 4 × 3/4 + 8 × 5/8 + 2 × 1/2 = 3 + 5 + 1 = 9; water = 1 + 3 + 1 = 5. So 9 : 5. Averaging the three ratios as if the volumes were equal is the trap.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-ratio-55", "question": "A starts a business with ₹60,000. B joins after 4 months with ₹80,000, and C joins 8 months after the start with ₹1,20,000. Out of a year-end profit of ₹1,15,000, what is B's share?", "options": ["₹40,000", "₹30,000", "₹35,000", "₹45,000"], "answer": 0, "explanation": "Capital × months: A = 60,000 × 12, B = 80,000 × 8, C = 1,20,000 × 4, i.e. 18 : 16 : 12 = 9 : 8 : 6. B's share = 8/23 × 1,15,000 = ₹40,000.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-ratio-56", "question": "Alloy X contains gold and copper in the ratio 2 : 3 and alloy Y in the ratio 4 : 1. How many kg of X must be used to make 30 kg of an alloy containing gold and copper in equal amounts?", "options": ["20 kg", "15 kg", "22.5 kg", "7.5 kg"], "answer": 2, "explanation": "Gold: X = 40%, Y = 80%, target = 50%. Alligation: X : Y = (80 − 50) : (50 − 40) = 3 : 1, so X = 3/4 × 30 = 22.5 kg.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-ratio-57", "question": "The present ages of A and B are in the ratio 4 : 5, and those of B and C in the ratio 6 : 7. Ten years from now, the sum of A's and C's ages will be 79 years. What is B's present age?", "options": ["25 years", "24 years", "30 years", "35 years"], "answer": 2, "explanation": "A : B : C = 24 : 30 : 35. A + C now = 79 − 20 = 59 = 59k, so k = 1 and B = 30. Subtracting only 10 years (not 10 for each person) gives the wrong total.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-ratio-58", "question": "When a man married, the ratio of his age to his wife's was 5 : 3. Now the ratio is 9 : 7. If the man is 45 years old now, how many years ago did they marry?", "options": ["18 years", "15 years", "25 years", "20 years"], "answer": 3, "explanation": "Ages at marriage 5k and 3k; after t years (5k + t)/(3k + t) = 9/7 gives 8k = 2t, so t = 4k. Now 5k + 4k = 45 gives k = 5 and t = 20 years. Check: 25, 15 then; 45, 35 now.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-ratio-59", "question": "Assertion (A): If 2A = 3B = 4C, then A : B : C = 2 : 3 : 4.\nReason (R): If 2A = 3B, then A : B = 3 : 2.", "options": ["A is true but R is false", "Both A and R are true, and R is the correct explanation of A", "Both A and R are false", "A is false but R is true"], "answer": 3, "explanation": "R is true (A/B = 3/2). Applying it to all three gives A : B : C = 1/2 : 1/3 : 1/4 = 6 : 4 : 3, so A is false.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-ratio-60", "question": "A vessel contains 80 litres of milk and water in the ratio 7 : 1. 16 litres of the mixture are drawn off and replaced with water, and the process is repeated once more. What is the ratio of milk to water now?", "options": ["3 : 2", "7 : 3", "14 : 11", "28 : 17"], "answer": 2, "explanation": "Milk starts at 70 L and each step keeps 64/80 = 4/5 of it: 70 × (4/5)² = 44.8 L. Water = 80 − 44.8 = 35.2 L, so the ratio is 44.8 : 35.2 = 14 : 11.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-ratio-61", "question": "If a : b = 2 : 3, b : c = 4 : 5 and c : d = 6 : 7, what is (a + b) : (c + d)?", "options": ["5 : 13", "16 : 35", "40 : 63", "8 : 13"], "answer": 3, "explanation": "Make the links match: a : b : c : d = 16 : 24 : 30 : 35. So (a + b) : (c + d) = 40 : 65 = 8 : 13.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-ratio-62", "question": "If (3x + 4y) : (5x − 2y) = 2 : 1, what is (x² + y²) : (x² − y²)?", "options": ["113 : 15", "65 : 33", "15 : 113", "8 : 7"], "answer": 0, "explanation": "3x + 4y = 10x − 4y gives 8y = 7x, so x : y = 8 : 7. Then (64 + 49) : (64 − 49) = 113 : 15.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-ratio-63", "question": "A invests twice as much as B, and B invests three-fourths as much as C. A's money is in the business for 6 months, B's for 8 months and C's for 12 months. Out of a profit of ₹27,000, what is C's share?", "options": ["₹13,500", "₹9,000", "₹12,000", "₹10,800"], "answer": 2, "explanation": "With C = 4: B = 3 and A = 6. Capital × months: A = 36, B = 24, C = 48, i.e. 3 : 2 : 4. C's share = 4/9 × 27,000 = ₹12,000.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-ratio-64", "question": "At a show, adult and child tickets cost in the ratio 3 : 2, and the numbers of adults and children are in the ratio 5 : 8. If ₹6,200 was collected in all, how much came from children's tickets?", "options": ["₹2,480", "₹3,815", "₹3,000", "₹3,200"], "answer": 3, "explanation": "Money ∝ price × number: adults 3 × 5 = 15, children 2 × 8 = 16. Children's share = 16/31 × 6,200 = ₹3,200.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id":"quant-ratio-65","question":"If 3A = 5B, what is A : B?","options":["3 : 5","5 : 3","15 : 1","8 : 3"],"answer":1,"explanation":"3A = 5B means A/B = 5/3. The number multiplying A goes with B in the ratio.","difficulty":"easy","source":"SSC CHSL · RRB Group D"},
  {"id":"quant-ratio-66","question":"₹1,560 is divided in the ratio 5 : 8. What is the smaller share?","options":["₹600","₹960","₹520","₹650"],"answer":0,"explanation":"Total parts = 13, one part = 120. Smaller share = 5 × 120 = ₹600.","difficulty":"easy","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-ratio-67","question":"What is the fourth proportional to 4, 10 and 18?","options":["7.2","24","40","45"],"answer":3,"explanation":"4 : 10 = 18 : x gives x = 10 × 18/4 = 45.","difficulty":"easy","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-ratio-68","question":"What is the ratio of 45 minutes to 2 hours?","options":["45 : 2","9 : 4","3 : 8","3 : 4"],"answer":2,"explanation":"Use the same unit: 45 : 120 = 3 : 8.","difficulty":"easy","source":"RRB Group D · SSC CHSL"},
  {"id":"quant-ratio-69","question":"A : B = 5 : 7. If B is 63, what is A?","options":["88.2","35","45","49"],"answer":2,"explanation":"One part = 63/7 = 9, so A = 5 × 9 = 45.","difficulty":"easy","source":"RRB Group D · SSC CHSL"},
  {"id":"quant-ratio-70","question":"What is the sub-duplicate ratio of 49 : 81?","options":["49² : 81²","7 : 9","9 : 7","2401 : 6561"],"answer":1,"explanation":"Sub-duplicate ratio means the ratio of square roots: √49 : √81 = 7 : 9.","difficulty":"easy","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-ratio-71","question":"What is the triplicate ratio of 2 : 3?","options":["8 : 27","6 : 9","4 : 9","√2 : √3"],"answer":0,"explanation":"Triplicate ratio is the ratio of cubes: 2³ : 3³ = 8 : 27.","difficulty":"easy","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-ratio-72","question":"If 40% of A equals 3/5 of B, what is A : B?","options":["2 : 3","6 : 5","5 : 6","3 : 2"],"answer":3,"explanation":"0.4A = 0.6B gives A/B = 0.6/0.4 = 3/2.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-ratio-73","question":"If A : B : C = 2 : 3 : 4, what is A/B : B/C : C/A?","options":["2 : 3 : 4","4 : 3 : 2","9 : 8 : 24","8 : 9 : 24"],"answer":3,"explanation":"A/B = 2/3, B/C = 3/4, C/A = 2. Multiply by 12: 8 : 9 : 24.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ratio-74","question":"The present ages of Priya and Neha are in the ratio 6 : 5 and add up to 66 years. What will be the ratio of their ages after 6 years?","options":["6 : 5","12 : 11","7 : 6","8 : 7"],"answer":2,"explanation":"Ages are 36 and 30 (66 split 6 : 5). After 6 years: 42 : 36 = 7 : 6.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-ratio-75","question":"Two numbers are in the ratio 7 : 9 and their LCM is 1,764. What is their sum?","options":["432","448","504","392"],"answer":1,"explanation":"Numbers are 7h and 9h with LCM 63h = 1,764, so h = 28. Sum = 16 × 28 = 448.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ratio-76","question":"In a class, boys and girls are in the ratio 7 : 8. On a rainy day 25% of the boys and 30% of the girls are absent. What is the ratio of boys to girls present?","options":["15 : 16","7 : 8","21 : 28","16 : 15"],"answer":0,"explanation":"Present: boys 7 × 0.75 = 5.25 and girls 8 × 0.7 = 5.6. Ratio 5.25 : 5.6 = 15 : 16.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-ratio-77","question":"If x : y = 5 : 3, what is (x² − y²) : (x² + y²)?","options":["8 : 17","2 : 8","16 : 9","17 : 8"],"answer":0,"explanation":"Put x = 5, y = 3: (25 − 9) : (25 + 9) = 16 : 34 = 8 : 17.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ratio-78","question":"A 45-litre mixture has milk and water in the ratio 4 : 1. How much milk must be added to make the ratio 5 : 1?","options":["5 litres","4.5 litres","11.25 litres","9 litres"],"answer":3,"explanation":"Milk = 36 L, water = 9 L. Water stays fixed, so milk must become 5 × 9 = 45 L: add 9 L.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-ratio-79","question":"The prices of petrol and diesel are in the ratio 5 : 4. If petrol becomes 20% dearer and diesel 25% dearer, what is the new ratio of their prices?","options":["5 : 4","24 : 25","6 : 5","4 : 5"],"answer":2,"explanation":"New prices: 5 × 1.2 = 6 and 4 × 1.25 = 5. Ratio 6 : 5.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-ratio-80","question":"A hostel has rooms for first-, second- and third-year students in the ratio 4 : 5 : 6. If these are increased by 25%, 20% and 50% respectively, what is the new ratio?","options":["4 : 5 : 6","5 : 6 : 9","6 : 5 : 9","5 : 7 : 9"],"answer":1,"explanation":"4 × 1.25 = 5, 5 × 1.2 = 6, 6 × 1.5 = 9. New ratio 5 : 6 : 9.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ratio-81","question":"Two numbers are in the ratio 3 : 4 and the difference of their squares is 252. What is the larger number?","options":["18","24","28","32"],"answer":1,"explanation":"(4k)² − (3k)² = 7k² = 252, so k = 6 and the larger number is 24.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-ratio-82","question":"If 15% of x = 25% of y = 40% of z, what is x : y : z?","options":["40 : 24 : 15","15 : 25 : 40","8 : 5 : 3","24 : 40 : 15"],"answer":0,"explanation":"x : y : z = 1/15 : 1/25 : 1/40. Multiply by 600 (LCM): 40 : 24 : 15.","difficulty":"moderate","source":"SSC CGL · SSC CPO"},
  {"id":"quant-ratio-83","question":"A 21-litre mixture has milk and water in the ratio 5 : 2. 7 litres of the mixture are taken out and replaced with milk. What is the new ratio of milk to water?","options":["5 : 2","15 : 4","22 : 7","17 : 4"],"answer":3,"explanation":"14 L remain with milk 10 L and water 4 L. Adding 7 L milk: 17 : 4.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-ratio-84","question":"Three varieties of rice costing ₹40, ₹48 and ₹60 per kg are mixed in the ratio 3 : 2 : 5. What is the cost of the mixture per kg?","options":["₹49.33","₹52","₹51.60","₹50.40"],"answer":2,"explanation":"(3 × 40 + 2 × 48 + 5 × 60)/10 = (120 + 96 + 300)/10 = ₹51.60. The simple average ₹49.33 ignores the quantities.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-ratio-85","question":"The daily wages of A and B are in the ratio 5 : 4. A works for 20 days and B for 25 days, and together they earn ₹18,000. How much does A earn?","options":["₹10,000","₹8,000","₹9,000","₹7,200"],"answer":2,"explanation":"Earnings ∝ wage × days: 5 × 20 = 100 and 4 × 25 = 100, so they earn equally. A gets ₹9,000.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-ratio-86","question":"A invests 3 times as much as B, and B invests 2/3 of what C invests. Out of a profit of ₹6,600, what is B's share?","options":["₹1,800","₹1,200","₹3,600","₹2,200"],"answer":1,"explanation":"Take C = 3: B = 2 and A = 6. Ratio 6 : 2 : 3 (11 parts). B = 2/11 × 6,600 = ₹1,200.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-ratio-87","question":"x varies inversely as the square of y, and x = 9 when y = 4. What is y when x = 16?","options":["3","2.25","5.33","12"],"answer":0,"explanation":"x × y² is constant = 9 × 16 = 144. For x = 16, y² = 9, so y = 3.","difficulty":"moderate","source":"SSC CGL · CDS"},
  {"id":"quant-ratio-88","question":"If a : b = 3 : 4, what is (5a − 3b) : (7a + 2b)?","options":["1 : 1","29 : 3","15 : 29","3 : 29"],"answer":3,"explanation":"Put a = 3, b = 4: (15 − 12) : (21 + 8) = 3 : 29.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-ratio-89","question":"Three friends share a cab hire of ₹7,200 in proportion to the distances they travel: 120 km, 150 km and 210 km. How much does the third friend pay?","options":["₹2,400","₹2,250","₹3,000","₹3,150"],"answer":3,"explanation":"120 : 150 : 210 = 4 : 5 : 7 (16 parts). Third friend = 7/16 × 7,200 = ₹3,150.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-ratio-90","question":"The sides of a triangle are in the ratio 1/2 : 1/3 : 1/4 and its perimeter is 104 cm. What is the longest side?","options":["52 cm","32 cm","48 cm","24 cm"],"answer":2,"explanation":"Multiply by 12: 6 : 4 : 3 (13 parts). Longest side = 6/13 × 104 = 48 cm.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ratio-91","question":"If 2A = 3B and 4B = 5C, what is A : C?","options":["8 : 15","15 : 8","5 : 2","3 : 5"],"answer":1,"explanation":"A = 1.5B and C = 0.8B, so A : C = 1.5 : 0.8 = 15 : 8.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-ratio-92","question":"A and B start a business with ₹40,000 and ₹60,000. After 4 months A adds ₹20,000 and B withdraws ₹20,000. Out of a year-end profit of ₹45,000, what is A's share?","options":["₹24,000","₹18,000","₹22,500","₹21,000"],"answer":0,"explanation":"A: 40 × 4 + 60 × 8 = 640; B: 60 × 4 + 40 × 8 = 560 (in thousand-months). Ratio 8 : 7, so A = 8/15 × 45,000 = ₹24,000.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-ratio-93","question":"Four years ago the ages of A and B were in the ratio 3 : 4. Four years from now they will be in the ratio 5 : 6. What is the sum of their present ages?","options":["36 years","28 years","44 years","40 years"],"answer":0,"explanation":"Four years ago: 3x and 4x. Eight years later: (3x + 8)/(4x + 8) = 5/6, so 18x + 48 = 20x + 40 and x = 4. Present ages 16 and 20; sum 36.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ratio-94","question":"Vessel A holds 16 litres of milk and water in the ratio 3 : 1, and vessel B holds 24 litres in the ratio 5 : 3. Both are emptied into a third vessel. What is the ratio of milk to water in it?","options":["8 : 4","4 : 1","13 : 27","27 : 13"],"answer":3,"explanation":"A: 12 milk, 4 water. B: 15 milk, 9 water. Together 27 : 13. Adding the ratios (8 : 4) ignores the different volumes.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ratio-95","question":"Pulses costing ₹90 per kg and ₹120 per kg are mixed. How many kg of the dearer variety must be mixed with 24 kg of the cheaper one to get a mixture worth ₹102 per kg?","options":["36 kg","12 kg","16 kg","18 kg"],"answer":2,"explanation":"Alligation: cheaper : dearer = (120 − 102) : (102 − 90) = 18 : 12 = 3 : 2. With 24 kg cheaper, dearer = 16 kg.","difficulty":"hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-ratio-96","question":"₹1,300 is shared among A, B and C so that if ₹20, ₹30 and ₹50 are taken away from their shares, the remainders are in the ratio 3 : 4 : 5. What is B's share?","options":["₹400","₹430","₹450","₹433"],"answer":1,"explanation":"Remainders total 1,300 − 100 = 1,200 in 12 parts, so one part = 100. B = 400 + 30 = ₹430.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ratio-97","question":"Three numbers are in the ratio 3 : 4 : 5. The sum of the largest and the smallest equals the middle number plus 52. What is the largest number?","options":["52","65","39","60"],"answer":1,"explanation":"3k + 5k = 4k + 52 gives 4k = 52, so k = 13 and the largest is 65.","difficulty":"hard","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-ratio-98","question":"A and B invest ₹3 lakh and ₹2 lakh. Each first receives 10% interest on capital from the profit, and the rest is shared equally. If the profit is ₹1,10,000, what does A get in all?","options":["₹60,000","₹66,000","₹55,000","₹50,000"],"answer":0,"explanation":"Interest: A ₹30,000, B ₹20,000. The remaining ₹60,000 is split equally. A gets 30,000 + 30,000 = ₹60,000.","difficulty":"hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-ratio-99","question":"A's salary is 20% more than B's, and C's salary is 25% less than A's. What is A : B : C?","options":["6 : 5 : 4","12 : 10 : 8","5 : 4 : 3","12 : 10 : 9"],"answer":3,"explanation":"Take B = 10: A = 12 and C = 12 × 0.75 = 9. So 12 : 10 : 9.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ratio-100","question":"If a : b = c : d, then (a² + c²) : (b² + d²) equals:","options":["a : b","ac : bd","a² : b²","(a + c) : (b + d)²"],"answer":2,"explanation":"Let a/b = c/d = k, so a = bk and c = dk. Then (a² + c²)/(b² + d²) = k²(b² + d²)/(b² + d²) = k² = a²/b².","difficulty":"hard","source":"SSC CGL · CDS"},
  {"id":"quant-ratio-101","question":"A invests for 8 months and B for 6 months, and their profits are in the ratio 4 : 5. What is the ratio of their capitals?","options":["4 : 5","3 : 5","16 : 15","5 : 3"],"answer":1,"explanation":"Capital ∝ profit ÷ time: 4/8 : 5/6 = 1/2 : 5/6 = 3 : 5.","difficulty":"hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-ratio-102","question":"A 50-litre car tank is half full of E10 fuel (petrol and ethanol in the ratio 90 : 10). It is then filled up with E20 fuel (80 : 20). What is the ratio of petrol to ethanol in the tank now?","options":["17 : 3","85 : 10","3 : 17","9 : 1"],"answer":0,"explanation":"Ethanol = 10% of 25 + 20% of 25 = 2.5 + 5 = 7.5 L out of 50 L, i.e. 15%. Petrol : ethanol = 85 : 15 = 17 : 3.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-ratio-103","question":"A jeweller mixes 24-carat gold with 18-carat gold to make 22-carat gold. How many grams of 18-carat gold should he add to 30 g of 24-carat gold?","options":["15 g","10 g","20 g","60 g"],"answer":0,"explanation":"Alligation on carats: 24k : 18k = (22 − 18) : (24 − 22) = 4 : 2 = 2 : 1. With 30 g of 24k, add 15 g of 18k.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ratio-104","question":"The ages of A, B and C add up to 90 years. Ten years ago their ages were in the ratio 1 : 2 : 3. What is C's present age?","options":["45 years","30 years","50 years","40 years"],"answer":3,"explanation":"Ten years ago the total was 90 − 30 = 60, split 1 : 2 : 3 as 10, 20, 30. C is now 30 + 10 = 40. Splitting 90 directly (45) forgets the ten years.","difficulty":"hard","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-ratio-105","question":"A trader sells part of 50 kg of sugar at 8% profit and the rest at 18% profit, making 14% profit overall. How much did he sell at 18% profit?","options":["20 kg","25 kg","30 kg","35 kg"],"answer":2,"explanation":"Alligation: 8% part : 18% part = (18 − 14) : (14 − 8) = 4 : 6 = 2 : 3. The 18% part = 3/5 × 50 = 30 kg.","difficulty":"hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-ratio-106","question":"A 40 g alloy contains gold, silver and copper in the ratio 5 : 3 : 2. How much silver must be added so that silver makes up half the alloy?","options":["8 g","16 g","12 g","20 g"],"answer":1,"explanation":"Silver = 12 g, the rest = 28 g, which stays fixed. For silver to be half, silver must also be 28 g: add 16 g.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ratio-107","question":"A concrete mix uses cement, sand and stone chips in the ratio 1 : 1.5 : 3 by volume. How many 0.04 m³ bags of cement are needed for 11 m³ of dry mix?","options":["55","50","40","44"],"answer":1,"explanation":"Cement = 1/5.5 of 11 m³ = 2 m³. Bags = 2 ÷ 0.04 = 50.","difficulty":"hard","source":"RRB JE · SSC JE"},
  {"id":"quant-ratio-108","question":"A starts a business with ₹50,000. B joins x months later with ₹75,000. At the end of the year they share the profit equally. What is x?","options":["4","6","3","8"],"answer":0,"explanation":"50,000 × 12 = 75,000 × (12 − x) gives 12 − x = 8, so x = 4.","difficulty":"hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-ratio-109","question":"A 50-litre mixture has milk and water in the ratio 4 : 1. 10 litres of it are removed and replaced with a mixture of milk and water in equal parts. What is the new ratio?","options":["4 : 1","32 : 13","9 : 4","37 : 13"],"answer":3,"explanation":"After removal: 32 L milk, 8 L water. Adding 5 L of each: 37 : 13.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ratio-110","question":"A and B invest ₹60,000 and ₹40,000. B manages the business and draws ₹1,000 a month as salary; the rest of the profit is shared in the ratio of capitals. If the yearly profit is ₹72,000, how much does B get in all?","options":["₹28,800","₹24,000","₹36,000","₹40,800"],"answer":2,"explanation":"Salary = ₹12,000. The remaining ₹60,000 is shared 3 : 2, so B gets ₹24,000. Total = ₹36,000.","difficulty":"hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-ratio-111","question":"Three farmers rent a pasture for ₹6,200. A grazes 8 buffaloes for 6 months, B 10 buffaloes for 4 months and C 12 buffaloes for 3 months. How much rent should C pay?","options":["₹2,000","₹2,480","₹1,800","₹2,067"],"answer":2,"explanation":"Buffalo-months: 48, 40 and 36, i.e. 12 : 10 : 9 (31 parts). C pays 9/31 × 6,200 = ₹1,800.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ratio-112","question":"Three numbers are in the ratio 3 : 4 : 7 and their product is 18,144. What is the largest number?","options":["35","42","49","28"],"answer":1,"explanation":"3k × 4k × 7k = 84k³ = 18,144, so k³ = 216 and k = 6. Largest = 42.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ratio-113","question":"The daily wages of a man, a woman and a child are in the ratio 5 : 3 : 2. A contractor pays ₹9,900 a day to 20 men, 15 women and 10 children. What is a child's daily wage?","options":["₹120","₹100","₹180","₹60"],"answer":0,"explanation":"Total parts = 20 × 5 + 15 × 3 + 10 × 2 = 165, so one part = ₹60. A child gets 2 parts = ₹120.","difficulty":"hard","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-ratio-114","question":"A salt solution is 15% salt. After 30 litres of water evaporate, it is 20% salt. How much solution was there at first?","options":["90 litres","150 litres","100 litres","120 litres"],"answer":3,"explanation":"Salt is fixed: 0.15V = 0.2(V − 30) gives 0.05V = 6, so V = 120 L.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ratio-115","question":"A starts with ₹2 lakh and adds ₹50,000 after every 3 months. B invests ₹3.5 lakh for the whole year. In what ratio should they share the profit?","options":["4 : 7","1 : 1","14 : 11","11 : 14"],"answer":3,"explanation":"A (in lakh-months): 2 × 3 + 2.5 × 3 + 3 × 3 + 3.5 × 3 = 33. B: 3.5 × 12 = 42. Ratio 33 : 42 = 11 : 14.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-ratio-116","question":"If x/(y + z) = y/(z + x) = z/(x + y) = k, what are the possible values of k?","options":["1/2 only","−1 only","1/2 or −1","2 or −1"],"answer":2,"explanation":"Adding numerators and denominators: k = (x + y + z)/(2(x + y + z)) = 1/2 when x + y + z ≠ 0. If x + y + z = 0, then y + z = −x and k = −1.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS"},
  {"id":"quant-ratio-117","question":"Three vessels contain milk and water in the ratios 3 : 1, 5 : 3 and 9 : 7. Mixtures are taken from them in the volume ratio 1 : 2 : 4 and combined. What is the ratio of milk to water in the result?","options":["17 : 7","17 : 11","3 : 2","11 : 17"],"answer":1,"explanation":"Milk = 1 × 3/4 + 2 × 5/8 + 4 × 9/16 = 0.75 + 1.25 + 2.25 = 4.25 out of 7. Water = 2.75. Ratio 4.25 : 2.75 = 17 : 11.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-ratio-118","question":"Milk costs a vendor ₹60 per litre. He mixes it with water and sells the mixture at ₹54 per litre, making a 25% profit. What is the ratio of water to milk?","options":["7 : 18","1 : 9","2 : 9","5 : 18"],"answer":0,"explanation":"Cost of the mixture = 54 ÷ 1.25 = ₹43.20 per litre. Alligation (water costs 0): water : milk = (60 − 43.2) : 43.2 = 16.8 : 43.2 = 7 : 18.","difficulty":"very-hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-ratio-119","question":"The present ages of a father and his son are in the ratio 8 : 3. Five years ago the product of their ages was 350. What is the father's present age?","options":["40 years","48 years","32 years","35 years"],"answer":0,"explanation":"(8x − 5)(3x − 5) = 350. Trying x = 5: 35 × 10 = 350 ✓. Father = 40 years.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ratio-120","question":"From a can of pure milk, one-fourth is taken out and replaced with water. Then one-third of the mixture is replaced with water, and then half of the new mixture is replaced with water. What is the final ratio of milk to water?","options":["1 : 2","1 : 4","3 : 5","1 : 3"],"answer":3,"explanation":"Milk left = 3/4 × 2/3 × 1/2 = 1/4 of the can. Milk : water = 1/4 : 3/4 = 1 : 3.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-ratio-121","question":"A's capital is three-fourths of B's. After 4 months A withdraws half his capital, and after 6 months B withdraws one-third of his. Out of a year-end profit of ₹39,000, what is A's share?","options":["₹16,714","₹19,500","₹14,625","₹13,000"],"answer":2,"explanation":"Take A = 3, B = 4. A: 3 × 4 + 1.5 × 8 = 24. B: 4 × 6 + (8/3) × 6 = 40. Ratio 3 : 5, so A = 3/8 × 39,000 = ₹14,625.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-ratio-122","question":"x : y : z = 2 : 3 : 5 and (x + y)(y + z)(z + x) = 7,560. What is x?","options":["4","6","9","3"],"answer":1,"explanation":"(5k)(8k)(7k) = 280k³ = 7,560, so k³ = 27 and k = 3. x = 2k = 6.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS"},
  {"id":"quant-ratio-123","question":"A sum is to be divided among A, B and C in the ratio 3 : 4 : 5. If it were divided in the ratio 4 : 5 : 6 instead, A would get ₹120 more. What is the sum?","options":["₹1,440","₹7,200","₹6,000","₹9,000"],"answer":1,"explanation":"A's share changes from 3/12 = 1/4 to 4/15, a rise of 1/60 of the sum. So the sum = 120 × 60 = ₹7,200 (B's share, 1/3, does not change at all).","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-ratio-124","question":"Jar A has 40 litres of pure milk and jar B has 40 litres of pure water. 10 litres are poured from A into B, and then 10 litres of the mixture are poured from B back into A. What is the ratio of milk to water in A now?","options":["4 : 1","3 : 1","5 : 1","8 : 1"],"answer":0,"explanation":"A keeps 30 L milk. B has 10 milk + 40 water (1 : 4). The 10 L returned has 2 L milk and 8 L water, so A has 32 : 8 = 4 : 1.","difficulty":"very-hard","source":"SSC CGL · CAT-style"},
  {"id":"quant-ratio-125","question":"A is twice as old as B was when A was as old as B is now. If their ages add up to 63 years, how old is A?","options":["42 years","27 years","32 years","36 years"],"answer":3,"explanation":"Let the age gap be d = A − B. When A was B's present age, B was B − d. So A = 2(B − d) = 2(2B − A), giving 3A = 4B. With A + B = 63: A = 36, B = 27.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"quant-ratio-126","question":"If a : b = 3 : 2 and b : c = 4 : 5, what is (a² + b² + c²) : (ab + bc + ca)?","options":["74 : 77","11 : 10","77 : 74","25 : 24"],"answer":2,"explanation":"a : b : c = 6 : 4 : 5. Then a² + b² + c² = 36 + 16 + 25 = 77 and ab + bc + ca = 24 + 20 + 30 = 74.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-ratio-127","question":"Vessel P has milk and water in the ratio 3 : 1 and vessel Q in the ratio 1 : 1. In what ratio should they be mixed to get milk and water in the ratio 2 : 1?","options":["1 : 2","3 : 1","2 : 1","1 : 1"],"answer":2,"explanation":"Milk fractions: P = 3/4, Q = 1/2, target = 2/3. Alligation: P : Q = (2/3 − 1/2) : (3/4 − 2/3) = 1/6 : 1/12 = 2 : 1.","difficulty":"very-hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-ratio-128","question":"A sum is divided among A, B and C so that A gets one-third of what B and C together get, and B gets two-sevenths of what A and C together get. If A gets ₹1,500, what is the total?","options":["₹4,500","₹6,000","₹5,250","₹7,500"],"answer":1,"explanation":"A = (S − A)/3 gives A = S/4; B = 2(S − B)/7 gives B = 2S/9. With A = 1,500, S = ₹6,000 (B = ₹1,333.33, C the rest).","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ratio-129","question":"If (a + b) : (b + c) : (c + a) = 6 : 7 : 8 and a + b + c = 21, what is c?","options":["9","7","5","8"],"answer":0,"explanation":"Adding: 2(a + b + c) = 21k = 42, so k = 2. Then a + b = 12, so c = 21 − 12 = 9.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"quant-ratio-130","question":"A 60-litre vessel holds liquids P, Q and R in the ratio 3 : 4 : 5. 12 litres of the mixture are removed and replaced with liquid P. What is the new ratio of P : Q : R?","options":["3 : 4 : 5","5 : 4 : 5","9 : 8 : 10","6 : 4 : 5"],"answer":3,"explanation":"48 L remain: P 12, Q 16, R 20. Adding 12 L of P gives 24 : 16 : 20 = 6 : 4 : 5.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-ratio-131","question":"Two schools have students in the ratio 5 : 7. If 30 students move from the second school to the first, the ratio becomes 4 : 5. How many students are there in all?","options":["1,200","960","1,350","1,080"],"answer":3,"explanation":"5(5x + 30) = 4(7x − 30) gives 25x + 150 = 28x − 120, so x = 90. Total = 12 × 90 = 1,080.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ratio-132","question":"A invests ₹20,000 for the whole year. B invests ₹30,000 but withdraws ₹10,000 after 6 months. C joins after 4 months with ₹25,000. Out of a profit of ₹37,000, what is C's share?","options":["₹10,000","₹12,500","₹11,250","₹9,250"],"answer":0,"explanation":"In thousand-months: A 240, B 180 + 120 = 300, C 25 × 8 = 200. Total 740, so C = 200/740 × 37,000 = ₹10,000.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-ratio-133","question":"The present ages of A and B are in the ratio 5 : 4. A's age 6 years ago equals B's age 2 years from now. How old is A?","options":["32 years","45 years","35 years","40 years"],"answer":3,"explanation":"5x − 6 = 4x + 2 gives x = 8, so A is 40 (B is 32).","difficulty":"hard","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-ratio-134","question":"If x : y = 2 : 3 and y : z = 4 : 5, what is (x + y + z) : (x − y + z)?","options":["35 : 19","11 : 35","35 : 11","7 : 3"],"answer":2,"explanation":"x : y : z = 8 : 12 : 15. Then (8 + 12 + 15) : (8 − 12 + 15) = 35 : 11.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-ratio-135","question":"Vessel A has milk and water in the ratio 3 : 2 and vessel B in the ratio 7 : 3. In what ratio must they be mixed to get milk and water in the ratio 2 : 1?","options":["2 : 1","1 : 2","3 : 7","1 : 1"],"answer":1,"explanation":"Milk fractions: A = 3/5, B = 7/10, target = 2/3. Alligation: A : B = (7/10 − 2/3) : (2/3 − 3/5) = 1/30 : 2/30 = 1 : 2.","difficulty":"very-hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-ratio-136","question":"₹3,450 is divided in the ratio 1/2 : 2/3 : 3/4. What is the largest share?","options":["₹1,200","₹1,350","₹900","₹1,150"],"answer":1,"explanation":"Multiply by 12: 6 : 8 : 9 (23 parts). One part = ₹150, so the largest = 9 × 150 = ₹1,350.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-ratio-137","question":"If 30% of x equals 0.5y and y : z = 3 : 4, what is x : z?","options":["5 : 4","3 : 4","5 : 3","4 : 5"],"answer":0,"explanation":"x = 0.5y/0.3 = 5y/3, so x : y = 5 : 3. With y : z = 3 : 4, x : z = 5 : 4.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-ratio-138","question":"10 kg of a brass alloy with copper and zinc in the ratio 3 : 2 is melted with 14 kg of another with the ratio 4 : 3. What is the ratio of copper to zinc in the new alloy?","options":["7 : 6","3 : 2","4 : 3","7 : 5"],"answer":3,"explanation":"Copper = 6 + 8 = 14 kg; zinc = 4 + 6 = 10 kg. Ratio 14 : 10 = 7 : 5.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ratio-139","question":"What is the mean proportional between (3 + √2) and (12 − √32)?","options":["√28 + 2","4√2","2√7","6"],"answer":2,"explanation":"√32 = 4√2, so the product = (3 + √2)(12 − 4√2) = 36 − 12√2 + 12√2 − 8 = 28. Mean proportional = √28 = 2√7.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS"},
];

export default questions;
